"""Common prospective admission budget for N/S/T/A native role calls.

This wrapper is inert until a harness uses it. Limits and protocol digest must
be explicit; no study is registered or generated by constructing it. Rendered
native prompt bytes, including repeated instructions, count toward input usage.
No credentials, environment values or provider profiles are recorded here.
"""
from contextlib import contextmanager
import fcntl
import os
from pathlib import Path
import re
import time

from specorganon.role_jobs import canonical, digest, _json, _write, _safe, JobStore
from specorganon.software_controller import executable_fingerprint
from scripts.controller_native_role import render_prompt


class StudyBudgetError(ValueError):
    pass


class StudyClockPause(ValueError):
    """Clock continuity unknown; admit nothing and never renew the budget."""


class CellBudget:
    def __init__(self, root, *, protocol_sha256, max_calls, max_total_input_bytes,
                 max_elapsed_seconds, transport, validate=None):
        if type(protocol_sha256) is not str or re.fullmatch('[0-9a-f]{64}', protocol_sha256) is None:
            raise StudyBudgetError('explicit immutable protocol digest required')
        if (type(max_calls) is not int or not 1 <= max_calls <= 40
                or type(max_total_input_bytes) is not int or not 1 <= max_total_input_bytes <= max_calls * 128000
                or type(max_elapsed_seconds) is not int or not 1 <= max_elapsed_seconds <= 6000):
            raise StudyBudgetError('invalid explicit common cell limits')
        self.root = _safe(root)
        self.root.mkdir(parents=True, mode=0o700, exist_ok=True)
        info = self.root.stat()
        if info.st_uid != os.geteuid() or info.st_mode & 0o022:
            raise StudyBudgetError('private owned budget journal required')
        self.transport = transport
        self.validate = validate or (lambda: None)
        policy = {'schema':1, 'protocol_sha256':protocol_sha256, 'max_calls':max_calls,
                  'max_total_input_bytes':max_total_input_bytes, 'max_elapsed_seconds':max_elapsed_seconds,
                  'max_rendered_input_bytes':128000}
        path = self.root / 'policy.json'
        with self._lock():
            if path.exists() and _json(path) != policy:
                raise StudyBudgetError('budget/protocol changed; never grow a running cell budget')
            if not path.exists(): _write(path, policy)
        self.policy = policy

    @contextmanager
    def _lock(self):
        fd = os.open(self.root / '.lock', os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            yield
        finally: os.close(fd)

    def _clock(self):
        clock = self.root / 'clock.json'
        if clock.exists():
            anchor = _json(clock)
            if anchor['boot_id_sha256'] != JobStore._boot_id():
                raise StudyClockPause('admission clock changed; no new job until continuity is resolved')
            elapsed = time.monotonic() - anchor['monotonic']
            if elapsed < 0 or elapsed >= self.policy['max_elapsed_seconds']:
                raise StudyBudgetError('global cell deadline exhausted')
        else:
            _write(clock, {'epoch':time.time(),'monotonic':time.monotonic(),
                           'boot_id_sha256':JobStore._boot_id()})

    @staticmethod
    def _id(job_id):
        if type(job_id) is not str or re.fullmatch('[A-Za-z0-9][A-Za-z0-9_-]{0,63}', job_id) is None:
            raise StudyBudgetError('invalid persistent native job ID')

    def call(self, job_id, role, request):
        self._id(job_id)
        if type(role) is not str or role not in {'author','review'} or type(request) is not dict or request.get('role') != role:
            raise StudyBudgetError('native role differs from request')
        _, rendered = render_prompt(canonical(request))
        size = len(rendered.encode('utf-8'))
        if size>self.policy['max_rendered_input_bytes']:
            raise StudyBudgetError('individual rendered prompt ceiling exhausted')
        binding = {'role':role, 'request_sha256':digest(canonical(request)), 'rendered_input_bytes':size}
        with self._lock():
            self.validate()
            folder = self.root / job_id
            if folder.exists():
                if not (folder / 'admission.json').exists() or _json(folder / 'admission.json') != binding:
                    raise StudyBudgetError('admitted request diverged or preparation uncertain')
                # The underlying transport validates its own closed receipt or
                # reconciles an uncertain handle. Never manufacture a packet or
                # reserve a replacement job because observation was interrupted.
                return self.transport.call(job_id, role, request)
            self._clock()
            history = [_json(p/'admission.json') for p in self.root.iterdir()
                       if p.is_dir() and (p/'admission.json').exists()]
            if len(history) >= self.policy['max_calls']:
                raise StudyBudgetError('common native call ceiling exhausted')
            if sum(h['rendered_input_bytes'] for h in history) + size > self.policy['max_total_input_bytes']:
                raise StudyBudgetError('common cumulative rendered input ceiling exhausted')
            folder.mkdir(mode=0o700)
            _write(folder / 'admission.json', binding)
            # Admission is durable before dispatch and remains consumed after
            # any provider/format failure. No inferred tokens or money appear.
            return self.transport.call(job_id, role, request)

    def measure(self, job_id, argv, files):
        self._id(job_id)
        binding = {'argv':argv, 'files_sha256':digest(canonical(files)),
                   'executable_sha256':executable_fingerprint(files, argv)}
        with self._lock():
            self.validate()
            folder = self.root / 'tests'; folder.mkdir(mode=0o700, exist_ok=True)
            path = folder / (job_id + '.json')
            if path.exists():
                if _json(path) != binding: raise StudyBudgetError('test binding changed')
                return self.transport.measure(job_id, argv, files)
            self._clock()
            history = [_json(p) for p in folder.glob('*.json')]
            if len(history) >= 2: raise StudyBudgetError('common two-test ceiling exhausted')
            if history and history[-1]['executable_sha256'] == binding['executable_sha256']:
                raise StudyBudgetError('second test requires changed executable inputs')
            _write(path, binding)
            return self.transport.measure(job_id, argv, files)

    def verify_test(self, *args, **kwargs):
        return self.transport.verify_test(*args, **kwargs)

    def test_record(self,job_id):
        return self.transport.test_record(job_id)

    def summary(self):
        with self._lock():
            history = [_json(p/'admission.json') for p in self.root.iterdir()
                       if p.is_dir() and (p/'admission.json').exists()]
            return {'admitted_native_jobs':len(history),
                    'admitted_public_tests':len(list((self.root/'tests').glob('*.json'))),
                    'rendered_input_bytes':sum(h['rendered_input_bytes'] for h in history),
                    'policy':self.policy,'token_usage':None,'monetary_cost':None}

full_text.src/specorganon/docker_roles.py:
"""Private host transport for isolated native roles and uncredentialed tests.

No credentials/sessions are copied. Original authorized profiles are mounted only
for their native role. A created container's handle is persisted before start;
an interrupted attachment without a host receipt remains uncertain and is never
restarted. Reconciliation kills that exact owned container, retaining its files.
The trusted operator owns the journals and Docker daemon; hashes do not attest it.
"""
from __future__ import annotations

from contextlib import contextmanager
import fcntl
import json
import os
from pathlib import Path
import re
import selectors
import shutil
import signal
import subprocess
import time

from .ledger import strict_json_loads, _open_regular_file
from .role_jobs import JobStore, JobError, UncertainJob, canonical, digest, _read, _json, _write, _safe


class DockerRoleError(ValueError):
    pass


class DockerRoles:
    _CODEX_REASONING_EFFORTS = ('low', 'medium', 'high', 'xhigh')

    def __init__(self, root, *, native_image, test_image, source_root, public_catalog,
                 author_provider='codex', author_model='gpt-6.1-sol',
                 reviewer_provider='gemini', reviewer_model='gemini-3.1-pro-high',
                 codex_volume='specorganon-lab_codex-home', gemini_profile='/home/stev/.gemini',
                 gemini_executable='/home/stev/.local/bin/agy', seccomp=None, test_timeout_seconds=120,
                 codex_reasoning_effort='low'):
        self.root = _safe(root); self.root.mkdir(parents=True, mode=0o700, exist_ok=True)
        self.source = _safe(source_root); self.catalog = _safe(public_catalog)
        self.images = {'native': self._image(native_image), 'test': self._image(test_image)}
        self.routes = {'author': (author_provider, author_model), 'review': (reviewer_provider, reviewer_model)}
        if any(provider not in {'codex', 'gemini'} or type(model) is not str or not model for provider, model in self.routes.values()):
            raise DockerRoleError('unsupported explicit native route')
        if (type(codex_reasoning_effort) is not str
                or codex_reasoning_effort not in self._CODEX_REASONING_EFFORTS):
            raise DockerRoleError('codex_reasoning_effort must be one of low/medium/high/xhigh')
        self.codex_reasoning_effort = codex_reasoning_effort
        if re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]*', codex_volume) is None:
            raise DockerRoleError('invalid original Codex volume name')
        self.volume = codex_volume; self.gemini_profile = _safe(gemini_profile)
        self.gemini_executable = _safe(gemini_executable)
        self.seccomp = _safe(seccomp) if seccomp is not None else None
        if type(test_timeout_seconds) is not int or not 1 <= test_timeout_seconds <= 120:
            raise DockerRoleError('test timeout must be 1..120 seconds')
        self.test_timeout = test_timeout_seconds
        self.store = JobStore(self.root / 'host-journal', max_jobs=80, max_elapsed_seconds=6000)
        policy = {'schema': 3, 'images': self.images, 'routes': self.routes, 'test_timeout_seconds': self.test_timeout,
                  'source_root': str(self.source), 'public_catalog_sha256': digest(_read(self.catalog)),
                  'codex_original_volume': self.volume, 'gemini_original_profile': str(self.gemini_profile),
                  'gemini_executable_sha256': digest(_read(self.gemini_executable, 536870912)),
                  'codex_reasoning_effort': self.codex_reasoning_effort,
                  'seccomp_sha256': digest(_read(self.seccomp)) if self.seccomp else None}
        path = self.root / 'transport-policy.json'
        if path.exists():
            existing = _json(path)
            if type(existing) is not dict or existing.get('schema') != 3:
                raise DockerRoleError('transport schema3 required; previous schema cannot resume silently')
            if existing != strict_json_loads(canonical(policy).decode()):
                raise DockerRoleError('transport policy changed; use an explicitly versioned run')
        else: _write(path, policy)

    @staticmethod
    def _cli(argv, *, allow_failure=False):
        command = ['/usr/bin/docker', *argv]
        process = subprocess.Popen(command, stdin=subprocess.DEVNULL,
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
        streams = {'stdout': bytearray(), 'stderr': bytearray()}; selector = selectors.DefaultSelector()
        deadline = time.monotonic() + 15
        try:
            for name in streams:
                pipe = getattr(process, name); os.set_blocking(pipe.fileno(), False)
                selector.register(pipe, selectors.EVENT_READ, name)
            while selector.get_map() or process.poll() is None:
                remaining = deadline - time.monotonic()
                if remaining <= 0: raise DockerRoleError('Docker control deadline exceeded')
                for key, _ in selector.select(min(remaining, .05)):
                    raw = os.read(key.fd, 65536)
                    if not raw: selector.unregister(key.fileobj); continue
                    if len(streams[key.data]) + len(raw) > 2097152:
                        raise DockerRoleError('Docker control response oversized')
                    streams[key.data].extend(raw)
            result = subprocess.CompletedProcess(command, process.returncode, bytes(streams['stdout']), bytes(streams['stderr']))
        finally:
            selector.close()
            try: os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError: pass
            process.wait(timeout=2)
            for pipe in (process.stdout, process.stderr): pipe.close()
        if result.returncode and not allow_failure: raise DockerRoleError('Docker control command failed: ' + argv[0])
        return result

    @classmethod
    def _image(cls, ref):
        if type(ref) is not str or re.fullmatch(r'sha256:[0-9a-f]{64}', ref) is None:
            raise DockerRoleError('inspect and pin immutable image ID before constructing transport')
        actual = cls._cli(['image', 'inspect', ref, '--format', '{{.Id}}']).stdout.decode().strip()
        if actual != ref: raise DockerRoleError('inspected image identity diverged')
        return ref

    @contextmanager
    def _lock(self):
        fd = _open_regular_file(self.root / '.transport.lock', os.O_RDWR | os.O_CREAT)
        try: fcntl.flock(fd, fcntl.LOCK_EX); yield
        finally: os.close(fd)

    @staticmethod
    def _inventory(path):
        return {str(p.relative_to(path)): digest(_read(p, 2097152))
                for p in sorted(path.rglob('*')) if p.is_file()}

    def _prepare(self, job_id, role, request, files=None):
        if type(job_id) is not str or re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]{0,63}', job_id) is None:
            raise DockerRoleError('invalid persistent job ID')
        folder = self.root / 'jobs' / job_id
        request_raw = canonical(request)
        if len(request_raw) > 128000: raise DockerRoleError('native request exceeds input limit')
        plan_path = folder / 'launch.json'
        if folder.exists():
            if not plan_path.exists(): raise UncertainJob('job preparation interrupted; inspect, do not replace')
            plan = _json(plan_path)
            if plan['role'] != role or plan['request_sha256'] != digest(request_raw):
                raise DockerRoleError('persistent job request/role changed')
            if self._inventory(folder / 'input') != plan['input_manifest']:
                raise DockerRoleError('prepared input bytes changed')
            return folder, plan
        folder.mkdir(parents=True, mode=0o700)
        inp = folder / 'input'; inp.mkdir(mode=0o700); (folder / 'output').mkdir(mode=0o700)
        (inp / 'request.json').write_bytes(request_raw)
        image = self.images['test' if role == 'test' else 'native']
        provider = None; model = None
        if role != 'test':
            provider, model = self.routes[role]
            shutil.copy2(self.source / 'scripts/controller_native_role.py', inp / 'bridge.py')
            shutil.copytree(self.source / 'src/specorganon', inp / 'library/specorganon', ignore=shutil.ignore_patterns('__pycache__'))
            if provider == 'codex': shutil.copy2(self.catalog, inp / 'public-models.json')
        else:
            from .software_controller import safe_file
            for name, text in files.items():
                target = inp / 'delivery' / safe_file(name); target.parent.mkdir(parents=True, mode=0o700, exist_ok=True)
                target.write_text(text)
        label = digest(canonical({'root': str(self.root), 'job_id': job_id}))[:24]
        name = 'specorganon-role-' + label
        args = ['create', '--name', name, '--label', 'specorganon.run=' + label, '--read-only', '--cap-drop=ALL',
                '--security-opt', 'no-new-privileges', '--memory', '1g', '--cpus', '2', '--pids-limit', '128',
                '--tmpfs', '/tmp:rw,nosuid,size=256m', '--mount', f'type=bind,src={inp},dst=/input,readonly',
                '--mount', f'type=bind,src={folder / "output"},dst=/output', '-e', 'TMPDIR=/output']
        if role == 'test':
            args += ['--network', 'none', '-e', 'HOME=/output', '-w', '/input/delivery', '--entrypoint', '', image, *request['argv']]
        else:
            if self.seccomp: args += ['--security-opt', 'seccomp=' + str(self.seccomp)]
            if provider == 'codex': args += ['--mount', f'type=volume,src={self.volume},dst=/home/codex/.codex']
            else:
                args += ['--mount', f'type=bind,src={self.gemini_profile},dst=/home/stev/.gemini',
                         '--mount', f'type=bind,src={self.gemini_executable},dst=/usr/local/bin/agy,readonly', '-e', 'HOME=/home/stev']
            args += ['-e', 'OPENAI_API_KEY=', '-e', 'PYTHONPATH=/input/library', '-e', 'SPECORGANON_ROLE_IMAGE_ID=' + image,
                     '-w', '/input', '--entrypoint', '/opt/specorganon/.venv/bin/python', image,
                     '/input/bridge.py', '--provider', provider, '--model', model, '--request', '/input/request.json', '--output-dir', '/output']
            if provider == 'codex':
                args += ['--model-catalog', '/input/public-models.json',
                         '--codex-reasoning-effort', self.codex_reasoning_effort]
        plan = {'schema': 1, 'job_id': job_id, 'role': role, 'provider': provider, 'model': model,
                'request_sha256': digest(request_raw), 'image_id': image, 'name': name, 'label': label,
                'create_argv': args, 'container_id': None, 'input_manifest': self._inventory(inp),
                'codex_reasoning_effort': self.codex_reasoning_effort if provider == 'codex' else None}
        # Persist the name/intent first. A crash after Docker create is reconciled
        # by that exact name and label; no second container or native role call.
        _write(plan_path, plan)
        return folder, plan

    def _inspect(self, plan):
        result = self._cli(['inspect', plan['name']], allow_failure=True)
        if result.returncode: return None
        records = strict_json_loads(result.stdout.decode())
        if type(records) is not list or len(records) != 1: raise DockerRoleError('invalid Docker inspection')
        value = records[0]
        if value['Config']['Labels'].get('specorganon.run') != plan['label'] or value['Image'] != plan['image_id']:
            raise DockerRoleError('container ownership/image binding diverged')
        return value

    def _execute(self, job_id, role, request, files=None):
        folder, plan = self._prepare(job_id, role, request, files)
        record = self._inspect(plan)
        if plan['container_id'] is None:
            if record is None:
                created = self._cli(plan['create_argv']).stdout.decode().strip()
                if re.fullmatch(r'[0-9a-f]{64}', created) is None: raise DockerRoleError('invalid created container handle')
                plan['container_id'] = created
            else: plan['container_id'] = record['Id']
            _write(folder / 'launch.json', plan); record = self._inspect(plan)
        if record is None or record['Id'] != plan['container_id']:
            raise UncertainJob('recorded container handle missing; never recreate native call')
        if (record['State']['Status'] != 'created'
                and not (self.store.root / job_id / 'receipt.json').exists()
                and not (self.store.root / job_id / 'started.json').exists()):
            self.reconcile(job_id); raise UncertainJob('container previously started without journal proof; never restart')
        if role == 'test' and (record['Config']['Cmd'] != request['argv'] or record['Config']['Entrypoint'] not in (None, [])):
            raise DockerRoleError('test container command differs from exact subject argv')
        argv = ['/usr/bin/docker', 'start', '--attach', plan['container_id']]
        try:
            result = self.store.execute(job_id, argv, request, cwd=self.root,
                timeout_seconds=self.test_timeout if role == 'test' else 180,
                metadata={'role': role, 'provider': plan['provider'], 'model': plan['model'],
                          'image_id': plan['image_id'], 'container_id': plan['container_id'],
                          'input_manifest': plan['input_manifest']},
                cancel_argv=['/usr/bin/docker', 'kill', plan['container_id']])
        except UncertainJob:
            # No inference from exit0/container state closes the lost host receipt.
            self.reconcile(job_id)
            raise
        if self._inventory(folder / 'input') != plan['input_manifest']:
            raise DockerRoleError('role/test input changed after dispatch')
        observed = self._inspect(plan)
        if observed is None: raise UncertainJob('terminal container handle disappeared; no outcome promotion')
        if observed['State']['Running']:
            self.reconcile(job_id); raise UncertainJob('owned container still live after attachment; no terminal promotion')
        _write(folder / 'terminal-container.json', {'id': plan['container_id'], 'exit_code': observed['State']['ExitCode'],
                                                  'image_id': observed['Image'], 'oom_killed': observed['State']['OOMKilled']})
        if (result['receipt']['exit_code'] != observed['State']['ExitCode']
                and not result['receipt']['timed_out'] and not result['receipt']['truncated_streams']):
            raise DockerRoleError('attachment and container exit code diverged without bounded cancellation')
        if observed['State']['OOMKilled']: raise DockerRoleError('container OOM killed; preserve failed execution')
        return folder, plan, result

    def reconcile(self, job_id):
        folder = self.root / 'jobs' / job_id; plan = _json(folder / 'launch.json'); value = self._inspect(plan)
        if value is None: outcome = 'handle_missing_uncertain'
        elif value['State']['Running']:
            self._cli(['kill', value['Id']], allow_failure=True)
            value = self._inspect(plan)
            if value is not None and value['State']['Running']: raise DockerRoleError('owned container could not be stopped')
            outcome = 'owned_container_killed_execution_uncertain'
        else: outcome = 'owned_container_stopped_execution_uncertain'
        _write(folder / 'reconciliation.json', {'schema': 1, 'outcome': outcome, 'name': plan['name'],
                                               'native_restarted': False, 'acceptance': False})
        return outcome

    def call(self, job_id, role, request):
        with self._lock():
            folder, plan, job = self._execute(job_id, role, request)
            receipt = job['receipt']
            if receipt['exit_code'] or receipt['timed_out'] or receipt['truncated_streams']:
                raise DockerRoleError('native role failed/inconclusive; preserve without replacement')
            packet = strict_json_loads(job['stdout'].decode())
            if packet.get('request_sha256') != plan['request_sha256'] or packet.get('provider') != plan['provider'] or packet.get('model') != plan['model']:
                raise DockerRoleError('native bridge request/provider/model binding diverged')
            return {**packet, 'actor': ('agent:' if role == 'author' else 'reviewer:') + plan['provider'] + '-isolated-' + role,
                    'receipt_ref': str(self.store.root / job_id / 'receipt.json'), 'provenance': 'native'}

    def measure(self, job_id, argv, files):
        if (type(argv) is not list or not argv or any(type(v) is not str or not v or '\0' in v for v in argv)
                or not argv[0].startswith('/') or len(canonical(argv)) > 16384):
            raise DockerRoleError('test needs bounded explicit absolute argv')
        request = {'schema': 1, 'argv': argv, 'delivery_tree_sha256': digest(canonical(files))}
        with self._lock():
            folder, plan, job = self._execute(job_id, 'test', request, files)
            measured = job['receipt']; result = {**measured, 'subject_argv': argv,
                'attachment_exit_code': measured['exit_code'],
                'exit_code': _json(folder / 'terminal-container.json')['exit_code'],
                'test_job_ref': str(self.store.root / job_id / 'receipt.json'),
                'delivery_tree_sha256': request['delivery_tree_sha256'], 'image_id': plan['image_id'],
                'container_id': plan['container_id'], 'provenance': 'actual_isolated_container',
                'passed': measured['exit_code'] == 0 and not measured['timed_out'] and not measured['truncated_streams']}
            _write(folder / 'measured-test.json', result)
            return result

    def verify_test(self, data, files, *, require_passed=True, require_current=True):
        path = _safe(data['test_job_ref'])
        if path.parent.parent != self.store.root: raise DockerRoleError('test receipt lies outside this private journal')
        job_id = path.parent.name; receipt = _json(path); actual = _json(self.root / 'jobs' / job_id / 'measured-test.json')
        terminal = _json(self.root / 'jobs' / job_id / 'terminal-container.json')
        self.store._validate_receipt(path.parent, job_id, receipt)
        if ((require_current and actual['delivery_tree_sha256'] != digest(canonical(files)))
                or data.get('delivery_tree_sha256', actual['delivery_tree_sha256']) != actual['delivery_tree_sha256']
                or actual['subject_argv'] != data['argv']
                or (require_passed and actual['passed'] is not True) or actual['test_job_ref'] != str(path)
                or actual['attachment_exit_code'] != receipt['exit_code'] or actual['exit_code'] != terminal['exit_code']
                or any(actual[k] != receipt[k] for k in ('timed_out', 'stdout_sha256', 'stderr_sha256'))):
            raise DockerRoleError('test receipt/current delivery diverged')
        for name in ('stdout', 'stderr'):
            if digest(_read(path.parent / (name + '.bin'))) != receipt[name + '_sha256']:
                raise DockerRoleError('test measured stream changed')
        return True

full_text.src/specorganon/role_jobs.py:
"""Bounded external jobs with persistent, non-retrying execution receipts.

This journal does not authenticate reviewers, approve phases or sandbox commands.
The delivery controller supplies isolated transports and applies engine guards.
An interrupted job without a receipt is uncertain, even if its process later exits.
The operator must keep the journal private and outside role mounts. Hashes detect
divergence; a writer controlling all records can fabricate a coherent journal.
Process-group cleanup handles owned children, not descendants escaping the group
or SIGKILL of this owner. Isolated transports must enforce their own lifecycle.
"""
from __future__ import annotations

from contextlib import contextmanager
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import re
import selectors
import signal
import stat
import subprocess
import time
import uuid

from .ledger import strict_json_loads


class JobError(ValueError):
    """A job cannot be admitted or its measured record has diverged."""


class UncertainJob(JobError):
    """Execution began but no closed receipt proves its process outcome."""


def canonical(value):
    try:
        return json.dumps(value, sort_keys=True, ensure_ascii=False,
                          separators=(",", ":"), allow_nan=False).encode()
    except (TypeError, ValueError, UnicodeError) as exc:
        raise JobError("job data is not finite JSON") from exc


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def _safe(path):
    path = Path(path).absolute()
    if any(p.is_symlink() for p in [path, *path.parents]):
        raise JobError("job path must not traverse a symlink")
    return path


def _parent(path, dir_fd=None):
    path = Path(path)
    if dir_fd is None:
        parts = path.absolute().parts[1:]
        fd = os.open("/", os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    else:
        if path.is_absolute(): raise JobError("anchored record name must be relative")
        parts = path.parts; fd = os.dup(dir_fd)
    try:
        if not parts or any(part in {".", "..", ""} for part in parts):
            raise JobError("invalid record components")
        for part in parts[:-1]:
            next_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            os.close(fd); fd = next_fd
        return fd, parts[-1]
    except BaseException:
        os.close(fd); raise


def _read(path, limit=2_097_152, *, dir_fd=None):
    parent_fd = None
    try:
        parent_fd, name = _parent(path, dir_fd)
        fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent_fd)
        with os.fdopen(fd, "rb") as file:
            before = os.fstat(file.fileno())
            if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or before.st_size > limit:
                raise JobError("job record must be bounded, singly linked regular data")
            raw = file.read(limit + 1)
            after = os.fstat(file.fileno())
        if len(raw) != before.st_size or (before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns):
            raise JobError("job record changed during read")
        return raw
    except OSError as exc:
        raise JobError(f"cannot read job record {Path(path).name}") from exc
    finally:
        if parent_fd is not None: os.close(parent_fd)


def _json(path, *, dir_fd=None):
    try:
        return strict_json_loads(_read(path, dir_fd=dir_fd).decode())
    except (ValueError, UnicodeError) as exc:
        raise JobError(f"invalid job JSON {Path(path).name}") from exc


def _write(path, value, *, dir_fd=None):
    parent_fd, name = _parent(path, dir_fd)
    temp = "." + name + "." + uuid.uuid4().hex
    try:
        fd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=parent_fd)
        with os.fdopen(fd, "wb") as file:
            file.write(canonical(value)); file.flush(); os.fsync(file.fileno())
        os.replace(temp, name, src_dir_fd=parent_fd, dst_dir_fd=parent_fd)
        os.fsync(parent_fd)
    finally:
        try: os.unlink(temp, dir_fd=parent_fd)
        except FileNotFoundError: pass
        os.close(parent_fd)


def _argv(value):
    if (type(value) is not list or not 1 <= len(value) <= 256
            or any(type(v) is not str or not v or "\0" in v for v in value)
            or not os.path.isabs(value[0]) or len(canonical(value)) > 131_072):
        raise JobError("job argv must be a bounded explicit vector with absolute executable")
    return value


def _positive(value, upper, name):
    if type(value) is not int or not 1 <= value <= upper:
        raise JobError(f"invalid {name} limit")
    return value


class JobStore:
    def __init__(self, root, *, max_jobs=40, max_elapsed_seconds=6000,
                 max_stream_bytes=2_097_152, max_request_bytes=128_000):
        self.root = _safe(root)
        self.root.mkdir(mode=0o700, parents=True, exist_ok=True)
        if not self.root.is_dir(): raise JobError("job root must be a directory")
        parent_fd, name = _parent(self.root)
        try: self._root_fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent_fd)
        finally: os.close(parent_fd)
        info = os.fstat(self._root_fd)
        if info.st_uid != os.geteuid() or info.st_mode & 0o022:
            raise JobError("journal root must be owned and not writable by other users")
        self.policy = {
            "schema": 3,
            "max_jobs": _positive(max_jobs, 1000, "job budget"),
            "max_elapsed_seconds": _positive(max_elapsed_seconds, 6000, "elapsed"),
            "max_stream_bytes": _positive(max_stream_bytes, 2_097_152, "stream"),
            "max_request_bytes": _positive(max_request_bytes, 128_000, "request"),
        }
        with self._lock():
            path = self.root / "policy.json"
            if path.exists():
                current = self._json(path)
                if type(current) is not dict or current.get("policy") != self.policy:
                    raise JobError("job policy changed; use a new explicitly versioned run")
            else:
                self._write(path, {"policy": self.policy, "created_epoch": time.time(),
                                  "created_monotonic": time.monotonic(), "boot_id_sha256": self._boot_id()})

    def __del__(self):
        fd = getattr(self, "_root_fd", None)
        if fd is not None:
            try: os.close(fd)
            except OSError: pass
            self._root_fd = None

    def _relative(self, path):
        return Path(path).relative_to(self.root)

    def _read(self, path, limit=2_097_152):
        return _read(self._relative(path), limit, dir_fd=self._root_fd)

    def _json(self, path):
        return _json(self._relative(path), dir_fd=self._root_fd)

    def _write(self, path, value):
        return _write(self._relative(path), value, dir_fd=self._root_fd)

    @staticmethod
    def _boot_id():
        # Linux monotonic timestamps survive process restarts, not host reboot.
        # An unknown/rebooted clock stops new admission; no silent reset.
        fd = os.open("/proc/sys/kernel/random/boot_id", os.O_RDONLY | os.O_NOFOLLOW)
        try: raw = os.read(fd, 128)
        finally: os.close(fd)
        # procfs reports size zero for this kernel-provided value; it is not a
        # persisted journal file. Validate the fixed, bounded UUID format.
        if re.fullmatch(rb"[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\n", raw) is None:
            raise JobError("unknown kernel boot clock")
        return digest(raw)

    @contextmanager
    def _lock(self):
        fd = os.open(".jobs.lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600, dir_fd=self._root_fd)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise JobError("job lock must be a singly linked regular file")
            fcntl.flock(fd, fcntl.LOCK_EX)
            named = os.stat(".jobs.lock", dir_fd=self._root_fd, follow_symlinks=False)
            if (named.st_dev, named.st_ino) != (info.st_dev, info.st_ino):
                raise JobError("job lock pathname replaced")
            yield
        finally:
            os.close(fd)

    def execute(self, job_id, argv, request, *, cwd, timeout_seconds=180, env=None,
                metadata=None, cancel_argv=None, stdin_bytes=None):
        if type(job_id) is not str or re.fullmatch(r"[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}", job_id) is None:
            raise JobError("invalid job ID")
        argv = _argv(argv)
        timeout_seconds = _positive(timeout_seconds, 180, "timeout")
        cwd = _safe(cwd)
        if not cwd.is_dir(): raise JobError("job cwd must exist")
        if env is not None and (type(env) is not dict or any(type(k) is not str or type(v) is not str or "\0" in k + v for k, v in env.items())):
            raise JobError("invalid process environment")
        if cancel_argv is not None: _argv(cancel_argv)
        if stdin_bytes is not None and (type(stdin_bytes) is not bytes or len(stdin_bytes) > 128_000):
            raise JobError("stdin must be bounded bytes")
        # Environment values can contain credentials: retain only their digest.
        effective_env = dict(os.environ) if env is None else dict(env)
        envelope = {"request": request, "argv": argv, "cwd": str(cwd),
                    "environment_sha256": digest(canonical(effective_env)),
                    "metadata": metadata, "timeout_seconds": timeout_seconds,
                    "cancel_argv": cancel_argv,
                    "stdin_sha256": digest(stdin_bytes) if stdin_bytes is not None else None}
        raw = canonical(envelope)
        if len(raw) > self.policy["max_request_bytes"]:
            raise JobError("job request exceeds budget")
        fingerprint = digest(raw)
        with self._lock():
            path = _safe(self.root / job_id)
            if path.exists() and not path.is_dir(): raise JobError("job path must be a directory")
            if (path / "receipt.json").exists():
                receipt = self._json(path / "receipt.json")
                if (type(receipt) is not dict or receipt.get("request_sha256") != fingerprint
                        or self._read(path / "request.json") != raw):
                    raise JobError("closed job inputs/argv changed")
                self._validate_receipt(path, job_id, receipt)
                measured = {}
                for name in ("stdout", "stderr"):
                    stream = self._read(path / (name + ".bin"), self.policy["max_stream_bytes"])
                    if digest(stream) != receipt.get(name + "_sha256") or len(stream) != receipt.get(name + "_bytes"):
                        raise JobError("closed job stream changed")
                    measured[name] = stream
                return {"reused": True, "receipt": receipt, **measured}
            if (path / "started.json").exists():
                raise UncertainJob(f"job {job_id} started without receipt; inspect its existing handle, do not restart")
            if path.exists(): raise JobError("job directory exists without admission record")
            policy = self._json(self.root / "policy.json")
            count = sum((p / "started.json").exists() for p in self.root.iterdir() if p.is_dir())
            if policy.get("boot_id_sha256") != self._boot_id():
                raise JobError("execution clock changed; new jobs require a versioned run")
            elapsed = time.monotonic() - policy["created_monotonic"]
            if elapsed < 0: raise JobError("invalid admission clock")
            remaining = self.policy["max_elapsed_seconds"] - elapsed
            # Reserve bounded cleanup before dispatch. This is a process budget,
            # not a guarantee against OS hangs or hostile journal writers.
            if count >= self.policy["max_jobs"] or remaining <= 10:
                raise JobError("job budget exhausted")
            os.mkdir(job_id, mode=0o700, dir_fd=self._root_fd)
            self._write(path / "request.json", envelope)
            started = {"schema": 1, "request_sha256": fingerprint, "started_epoch": time.time(),
                       "pid": None, "metadata": metadata}
            self._write(path / "started.json", started)
            receipt = self._run(path, argv, cwd, effective_env, min(timeout_seconds, remaining - 10), cancel_argv, started, stdin_bytes)
            receipt.update(schema=1, job_id=job_id, request_sha256=fingerprint,
                           argv=argv, cwd=str(cwd), metadata=metadata)
            receipt.setdefault("stdin_bytes_sent", 0)
            receipt.setdefault("stdin_bytes_expected", len(stdin_bytes or b""))
            receipt.setdefault("stdin_complete", receipt["stdin_bytes_sent"] == receipt["stdin_bytes_expected"])
            # Close/fsync both streams before the sole terminal checkpoint.
            self._write(self.root / (".complete-" + job_id + ".json"), {
                "schema": 1, "receipt_sha256": digest(canonical(receipt)),
                "started_sha256": digest(self._read(path / "started.json")),
                "request_sha256": fingerprint})
            self._write(path / "receipt.json", receipt)
            return {"reused": False, "receipt": receipt,
                    **{name: self._read(path / (name + ".bin")) for name in ("stdout", "stderr")}}

    def _validate_receipt(self, path, job_id, value):
        fields = {"schema", "job_id", "request_sha256", "argv", "cwd", "metadata", "exit_code",
                  "timed_out", "truncated_streams", "duration_seconds", "finished_epoch", "cancel_exit_code",
                  "stdin_bytes_sent", "stdin_bytes_expected", "stdin_complete", "stdout_bytes",
                  "stderr_bytes", "stdout_sha256", "stderr_sha256"}
        if (set(value) != fields or type(value["schema"]) is not int or value["schema"] != 1
                or value["job_id"] != job_id or type(value["exit_code"]) is not int
                or type(value["timed_out"]) is not bool or type(value["stdin_complete"]) is not bool
                or any(type(value[k]) is not int or value[k] < 0 for k in
                       ("stdin_bytes_sent", "stdin_bytes_expected", "stdout_bytes", "stderr_bytes"))
                or any(type(value[k]) not in (int, float) or not math.isfinite(value[k]) or value[k] < 0
                       for k in ("duration_seconds", "finished_epoch"))
                or type(value["truncated_streams"]) is not list
                or any(type(v) is not str or v not in {"stdout", "stderr"} for v in value["truncated_streams"])
                or len(set(value["truncated_streams"])) != len(value["truncated_streams"])
                or value["cancel_exit_code"] is not None and type(value["cancel_exit_code"]) is not int
                or value["stdin_bytes_sent"] > value["stdin_bytes_expected"]
                or value["stdin_complete"] != (value["stdin_bytes_sent"] == value["stdin_bytes_expected"])):
            raise JobError("invalid terminal receipt schema")
        admission = self._json(path / "started.json")
        closing = self._json(self.root / (".complete-" + job_id + ".json"))
        if (type(closing) is not dict or type(admission) is not dict
                or closing.get("receipt_sha256") != digest(canonical(value))
                or closing.get("started_sha256") != digest(self._read(path / "started.json"))
                or closing.get("request_sha256") != value["request_sha256"]
                or admission.get("request_sha256") != value["request_sha256"]
                or admission.get("metadata") != value["metadata"]):
            raise JobError("terminal receipt differs from admission/closing record")

    def _run(self, path, argv, cwd, env, timeout, cancel_argv, started, stdin_bytes):
        streams = {}; process = None; selector = None
        began = time.monotonic(); sizes = {"stdout": 0, "stderr": 0}
        timed_out = False; truncated = []; cancel_exit = None; sent = 0
        stopped_at = None
        try:
            for name in ("stdout", "stderr"):
                parent_fd, leaf = _parent(self._relative(path / (name + ".bin")), self._root_fd)
                try:
                    fd = os.open(leaf, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                                 0o600, dir_fd=parent_fd)
                finally: os.close(parent_fd)
                streams[name] = os.fdopen(fd, "wb")
            try:
                process = subprocess.Popen(argv, cwd=cwd, env=env,
                    stdin=subprocess.PIPE if stdin_bytes is not None else subprocess.DEVNULL,
                    stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
            except OSError as exc:
                message = f"{type(exc).__name__}: process could not start\n".encode()
                streams["stderr"].write(message[:self.policy["max_stream_bytes"]])
                if len(message) > self.policy["max_stream_bytes"]: truncated.append("stderr")
                return self._finish(streams, path, 127, False, truncated, began, None)
            # Every operation after spawn is covered by the cleanup finally.
            started["pid"] = process.pid
            self._write(path / "started.json", started)
            selector = selectors.DefaultSelector()
            for name in ("stdout", "stderr"):
                pipe = getattr(process, name); os.set_blocking(pipe.fileno(), False)
                selector.register(pipe, selectors.EVENT_READ, name)
            if stdin_bytes:
                os.set_blocking(process.stdin.fileno(), False)
                selector.register(process.stdin, selectors.EVENT_WRITE, "stdin")
            elif process.stdin is not None: process.stdin.close()
            # Pipe closure does not prove process termination. Conversely, a
            # descendant retaining pipes cannot extend the admitted deadline.
            while selector.get_map() or process.poll() is None:
                now = time.monotonic()
                if stopped_at is None and now - began >= timeout:
                    timed_out = True; stopped_at = now; self._terminate(process)
                if stopped_at is not None and cancel_argv is not None and cancel_exit is None:
                    cancel_exit = self._cancel(cancel_argv, cwd, env)
                if stopped_at is not None and time.monotonic() - stopped_at >= 2:
                    for key in list(selector.get_map().values()):
                        selector.unregister(key.fileobj); key.fileobj.close()
                    break
                for key, _ in selector.select(0.05):
                    if key.data == "stdin":
                        try:
                            if stopped_at is None:
                                sent += os.write(key.fileobj.fileno(), memoryview(stdin_bytes)[sent:sent + 8192])
                        except BrokenPipeError:
                            selector.unregister(key.fileobj); key.fileobj.close(); continue
                        except BlockingIOError: continue
                        if stopped_at is not None or sent == len(stdin_bytes):
                            selector.unregister(key.fileobj); key.fileobj.close()
                        continue
                    try: block = os.read(key.fileobj.fileno(), 8192)
                    except BlockingIOError: continue
                    if not block:
                        selector.unregister(key.fileobj); key.fileobj.close(); continue
                    name = key.data; room = self.policy["max_stream_bytes"] - sizes[name]
                    streams[name].write(block[:room]); sizes[name] += min(len(block), room)
                    # Keep observed prefixes inspectable when this owner is
                    # SIGKILLed before a terminal receipt. This is not closure.
                    streams[name].flush()
                    if len(block) > room and name not in truncated:
                        truncated.append(name)
                        if stopped_at is None:
                            stopped_at = time.monotonic(); self._terminate(process)
            code = process.wait(timeout=2)
            receipt = self._finish(streams, path, code, timed_out, truncated, began, cancel_exit)
            receipt.update(stdin_bytes_sent=sent, stdin_bytes_expected=len(stdin_bytes or b""),
                           stdin_complete=sent == len(stdin_bytes or b""))
            return receipt
        except BaseException:
            if process is not None and cancel_argv is not None and cancel_exit is None:
                self._terminate(process); self._cancel(cancel_argv, cwd, env)
            raise
        finally:
            if process is not None:
                self._terminate(process)
                try: process.wait(timeout=2)
                except subprocess.TimeoutExpired: pass
                for name in ("stdout", "stderr", "stdin"):
                    pipe = getattr(process, name)
                    if pipe is not None and not pipe.closed: pipe.close()
            if selector is not None: selector.close()
            for stream in streams.values():
                if not stream.closed: stream.close()

    @classmethod
    def _cancel(cls, argv, cwd, env):
        process = None
        try:
            process = subprocess.Popen(argv, stdin=subprocess.DEVNULL, cwd=cwd, env=env,
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
            return process.wait(timeout=2)
        except (OSError, subprocess.TimeoutExpired): return -1
        finally:
            if process is not None:
                cls._terminate(process)
                try: process.wait(timeout=2)
                except subprocess.TimeoutExpired: pass

    @staticmethod
    def _terminate(process):
        try: os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError: pass

    def _finish(self, streams, path, code, timed_out, truncated, began, cancel_exit):
        for stream in streams.values():
            stream.flush(); os.fsync(stream.fileno()); stream.close()
        receipt = {"exit_code": code, "timed_out": timed_out, "truncated_streams": truncated,
                   "duration_seconds": time.monotonic() - began, "finished_epoch": time.time(),
                   "cancel_exit_code": cancel_exit}
        for name in ("stdout", "stderr"):
            raw = self._read(path / (name + ".bin"), self.policy["max_stream_bytes"])
            receipt[name + "_bytes"] = len(raw); receipt[name + "_sha256"] = digest(raw)
        return receipt

